const trial=()=>api.campaign.trials.find(t=>t.dualLight),contact=()=>{const p=api.player,t=trial();return t.bridges.some(b=>p.onGround&&Math.abs(p.y+p.h-b.row*16)<.7&&p.x+p.w>t.x0+b.col*16&&p.x<t.x0+(b.col+b.width)*16);};
